/**
 * Which translator shows a page in the chosen language.
 *
 * English is the source text. Amharic comes from the local phrase catalogue everywhere. Oromo,
 * Tigrinya and Somali come from their local catalogues on the routes those cover (COMPLETE_ROUTES,
 * generated by `node scripts/i18n.mjs sync`); elsewhere the
 * Google Website Translator is the fallback. Google sends the visible text of the page to Google,
 * so it is never used on pages that show a person's own case, health or account details: there the
 * local catalogue translates what it can and the rest stays in English.
 */
import { CATALOGUE_LANGUAGES, COMPLETE_ROUTES, type CatalogueLanguage } from "./phrases/sections";

export type TranslationEngine = "none" | "local" | "google";

/** Pages whose text must never leave the device for translation. */
const PRIVATE_PATHS = [
  /^\/case(?:-[a-z-]+)?(?:\/|$)/, // the person's cases, and the review consoles that show them
  /^\/diagnostic(?:\/|$)/,
  /^\/intake(?:\/|$)/,
  /^\/report(?:\/|$)/,
  /^\/profile(?:\/|$)/,
  /^\/messages(?:\/|$)/,
  /^\/account(?:\/|$)/,
  /^\/business\/[^/]+\/cases(?:\/|$)/,
];

export function isPrivatePath(pathname: string): boolean {
  const path = pathname.split(/[?#]/, 1)[0] || "/";
  return PRIVATE_PATHS.some((pattern) => pattern.test(path));
}

export function isCatalogueLanguage(language: string): language is CatalogueLanguage {
  return (CATALOGUE_LANGUAGES as readonly string[]).includes(language);
}

/** The first path segment, which names a route's phrase section. */
export function routeSection(pathname: string): string {
  return pathname.split(/[?#]/, 1)[0].split("/")[1] ?? "";
}

/** True when the language's catalogue covers this route's own section. */
export function hasLocalSection(language: string, pathname: string): boolean {
  if (!isCatalogueLanguage(language)) return false;
  const routes = COMPLETE_ROUTES[language];
  return routes.includes("*") || routes.includes(routeSection(pathname));
}

export function translationEngine(language: string, pathname: string): TranslationEngine {
  if (language === "en" || !isCatalogueLanguage(language)) return "none";
  if (language === "am") return "local";
  if (isPrivatePath(pathname) || hasLocalSection(language, pathname)) return "local";
  return "google";
}
